import { computeEtag, hasMatchingEtag } from "../../utils/etag.js";
import { ResponseBuilder } from "../../../../security/index.js";
import { getRendererForProject } from "../../../shared/renderer-factory.js";
import { shouldUseNoCacheHeadersFromHandler } from "../../../context/enriched-context.js";
import { withSpan } from "../../../../observability/tracing/otlp-setup.js";
import { serverLogger } from "../../../../utils/index.js";
import { VeryfrontError } from "../../../../errors/index.js";
import { createHandlerDependencyPinningSource } from "../../utils/dependency-pinning-source.js";
import { readSnapshotQuery, resolveSnapshotForRequest, snapshotConflictResponse, snapshotStoreFailureResponse, stripSnapshotQuery, } from "../../utils/dependency-snapshot-protocol.js";
function isPageModuleNotFound(error) {
    return error instanceof VeryfrontError &&
        (error.status === 404 || error.slug === "file-not-found" || error.slug === "page-not-found");
}
export function handlePageModule(req, pathname, ctx, createResponseBuilder, respond, getErrorMessage) {
    return withSpan("module.page.handle", async () => {
        try {
            const slugPath = pathname
                .replace("/_veryfront/pages/", "")
                .replace(/\.js$/, "")
                .replace(/\/$/, "");
            const slug = slugPath || "index";
            const requestUrl = new URL(req.url);
            const dependencyPinningSource = createHandlerDependencyPinningSource(ctx);
            const resolution = await resolveSnapshotForRequest(dependencyPinningSource, readSnapshotQuery(requestUrl));
            if (resolution.kind === "conflict") {
                return respond(snapshotConflictResponse(createResponseBuilder(ctx), req, ctx.securityConfig));
            }
            const dependencySnapshot = resolution.snapshot;
            const applicationUrl = stripSnapshotQuery(requestUrl);
            const renderer = await getRendererForProject(ctx);
            const { pageModule } = await renderer.renderPage(slug, {
                params: undefined,
                props: undefined,
                url: applicationUrl,
                dependencyPinningCacheKey: dependencySnapshot.cacheKey,
                dependencyPinningDependencies: dependencySnapshot.dependencies,
                dependencyPinningConfiguredVersions: dependencySnapshot.configuredVersions,
                dependencyPinningSource,
            });
            const code = pageModule?.code;
            if (!code) {
                return respond(ResponseBuilder.error(404, "Module not found", req, {
                    securityConfig: ctx.securityConfig,
                    corsConfig: ctx.securityConfig?.cors,
                }));
            }
            const etag = computeEtag(code);
            const builder = createResponseBuilder(ctx)
                .withCORS(req, ctx.securityConfig?.cors)
                .withSecurity(ctx.securityConfig ?? undefined, req);
            if (hasMatchingEtag(req, etag)) {
                return respond(builder.notModified(etag));
            }
            const cacheMode = shouldUseNoCacheHeadersFromHandler(ctx) ? "no-cache" : "short";
            return respond(builder.withCache(cacheMode).withETag(etag).javascript(code, 200));
        }
        catch (error) {
            const unavailable = snapshotStoreFailureResponse(error, createResponseBuilder(ctx), req, ctx.securityConfig);
            if (unavailable)
                return respond(unavailable);
            if (isPageModuleNotFound(error)) {
                return respond(ResponseBuilder.error(404, "Module not found", req, {
                    securityConfig: ctx.securityConfig,
                    corsConfig: ctx.securityConfig?.cors,
                }));
            }
            // Log the full error server-side but return a generic message
            // to avoid leaking internal details (Babel/TS errors, file paths, etc.)
            serverLogger.error("[page-module] Failed to generate module", {
                pathname,
                error: getErrorMessage(error),
            });
            return respond(ResponseBuilder.error(500, "Failed to generate module", req, {
                securityConfig: ctx.securityConfig,
                corsConfig: ctx.securityConfig?.cors,
            }));
        }
    }, {
        "module.page.pathname": pathname,
        "module.page.projectSlug": ctx.projectSlug || "unknown",
    });
}
